/**
 * Add two numbers.
 * @param {number} a
 * @param {number} b
 * @returns {number}
 */
export function add(a, b) {
  return a + b;
}

/**
 * Turn a string into a URL-friendly slug: trim, lowercase, replace each run
 * of non-alphanumeric characters with a single "-", and strip leading and
 * trailing "-".
 * @param {string} s
 * @returns {string}
 */
export function slugify(s) {
  return String(s)
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}
EOF
