Bootstraps the ESM Node project with two exported utilities.

Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>" && git log --oneline

cat > index.test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { add, slugify } from './index.js';

test('add sums positive integers', () => {
  assert.equal(add(2, 3), 5);
});

test('add handles negatives and zero', () => {
  assert.equal(add(-4, 1), -3);
  assert.equal(add(0, 0), 0);
});

test('add handles floats', () => {
  assert.ok(Math.abs(add(0.1, 0.2) - 0.3) < Number.EPSILON);
});

test('slugify lowercases and joins words with dashes', () => {
  assert.equal(slugify('Hello World'), 'hello-world');
});

test('slugify collapses runs of punctuation and whitespace', () => {
  assert.equal(slugify('Node.js -- is   great!!'), 'node-js-is-great');
});

test('slugify strips leading and trailing separators', () => {
  assert.equal(slugify('  --Trim me--  '), 'trim-me');
});

test('slugify keeps digits', () => {
  assert.equal(slugify('Top 10 Tips'), 'top-10-tips');
});

test('slugify returns an empty string for empty or separator-only input', () => {
  assert.equal(slugify(''), '');
  assert.equal(slugify('!!! ---'), '');
});
EOF
