/**
 * Internal string helpers shared by the library's modules. Not part of the
 * public API: index.js does not re-export them.
 * @module lib/util
 */

/**
 * Escape every character that has a special meaning in a regular expression,
 * so the result matches `str` literally when passed to `new RegExp()`.
 *
 * Escaped characters: `. * + ? ^ $ { } ( ) | [ ] \`
 *
 * @param {string} str - The text to escape.
 * @returns {string} `str` with each regex metacharacter prefixed by `\`.
 * @example
 * escapeRegExp('a.b*c'); // 'a\\.b\\*c'
 * new RegExp(escapeRegExp('1+1=2')).test('1+1=2'); // true
 */
export function escapeRegExp(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * Remove every leading and trailing occurrence of `char` from `str`.
 * Occurrences in the middle of the string are kept. `char` is matched
 * literally, so regex metacharacters such as `.` are safe to pass.
 *
 * @param {string} str - The text to trim.
 * @param {string} char - The character (or substring) to strip from both ends.
 * @returns {string} `str` without leading or trailing runs of `char`.
 * @example
 * trimChar('--a-b--', '-'); // 'a-b'
 * trimChar('..x..', '.');   // 'x'
 */
export function trimChar(str, char) {
  const c = escapeRegExp(char);
  return str.replace(new RegExp(`^(?:${c})+|(?:${c})+$`, 'g'), '');
}
EOF
