/**
 * URL slug generation.
 * @module lib/slugify
 */

import { trimChar } from './util.js';

/**
 * Turn a string into a URL-friendly slug. In order, it:
 *
 * 1. converts `s` to a string with `String(s)`;
 * 2. trims leading and trailing whitespace;
 * 3. lowercases it;
 * 4. replaces each run of characters outside `a-z` and `0-9` with one `-`;
 * 5. strips leading and trailing `-`.
 *
 * Only ASCII letters and digits survive; non-ASCII letters such as `è` count
 * as separators. Input with no ASCII letters or digits yields `''`.
 *
 * @param {string} s - The text to slugify. Non-strings are coerced with `String()`.
 * @returns {string} A slug made of lowercase ASCII letters, digits and single
 *   `-` separators, with no leading or trailing `-`.
 * @example
 * slugify('  Hello, World!  ');    // 'hello-world'
 * slugify('--Already--Slugged--'); // 'already-slugged'
 * slugify('Crème brûlée');         // 'cr-me-br-l-e'
 */
export function slugify(s) {
  const slug = String(s)
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-');
  return trimChar(slug, '-');
}
EOF
